// Mass Effect AP Setup: finds the Mass Effect LE and Archipelago folders, installs each game's world, bridge and mod
// (ME1 and ME2, see Profiles.cs), writes the player's YAML into Archipelago's Players folder and launches the game.
// Seeds are still generated by Archipelago (Save + Generate runs it) and hosted on archipelago.gg.
// Payload: one folder per game next to the exe (ME1\, ME2\) with the apworld, ASI\ (bridge), the mod folder and, for
// ME2, the AP ASI Loader (bink2w64.dll).
//
// Command line (tests; output goes to the calling console):
//   --install <ME1|ME2> --game <LE folder> --ap <Archipelago folder> [--payload <dir>] [--state <dir>] [--keep-movie <file>]...
//   --uninstall <ME1|ME2> --game ... --ap ... [--payload <dir>] [--state <dir>]
//   --check <ME1|ME2> --game ... --ap ... [--payload <dir>]     (what Launch would refuse; exit code 1 if anything)
//   --le1-toc <BioGame folder> <out file>                      (the LE1 game TOC this app writes)
//   --write-yaml <ME1|ME2> <file> [slot] [preset]
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
using Microsoft.Win32;

namespace APSetup;

static class Program
{
    [DllImport("kernel32.dll")] static extern bool AttachConsole(int processId);

    [STAThread]
    static int Main(string[] args)
    {
        ApplicationConfiguration.Initialize();
        if (args.Length > 0 && args[0].StartsWith("--"))
        {
            AttachConsole(-1);
            try { return Cli(args); }
            catch (Exception ex) { Console.Error.WriteLine("ERROR: " + ex.Message); return 2; }
        }
        Application.Run(new MainForm());
        return 0;
    }

    static int Cli(string[] args)
    {
        string Arg(string name, string fallback = null)
        {
            int i = Array.IndexOf(args, name);
            return i >= 0 && i + 1 < args.Length ? args[i + 1] : fallback;
        }
        GameProfile Profile(string id) => GameProfile.All.FirstOrDefault(p => p.Id.Equals(id, StringComparison.OrdinalIgnoreCase))
            ?? throw new ArgumentException($"unknown game {id} (ME1 or ME2)");
        Installer Make(GameProfile p) => new(p, Arg("--game"), Arg("--ap"), Arg("--payload", Path.Combine(AppContext.BaseDirectory, p.Id)),
                                              Arg("--state", Installer.DefaultStateDir(p)));
        switch (args[0])
        {
            case "--install":
            {
                var installer = Make(Profile(args[1]));
                var options = new Installer.Options();
                for (int i = 0; i < args.Length - 1; i++)
                    if (args[i] == "--keep-movie") options.KeepMovies.Add(args[i + 1]);
                installer.Install(options);
                installer.Log.ForEach(Console.WriteLine);
                return 0;
            }
            case "--uninstall":
            {
                var installer = Make(Profile(args[1]));
                installer.Uninstall();
                installer.Log.ForEach(Console.WriteLine);
                return 0;
            }
            case "--check":
            {
                var problems = Make(Profile(args[1])).LaunchProblems();
                problems.ForEach(Console.WriteLine);
                Console.WriteLine(problems.Count == 0 ? "ready to launch" : $"{problems.Count} problem(s)");
                return problems.Count == 0 ? 0 : 1;
            }
            case "--le1-toc":
                File.WriteAllBytes(args[2], Installer.Le1Toc(args[1]));
                Console.WriteLine($"wrote {args[2]}");
                return 0;
            case "--toc-list":   // <PCConsoleTOC.bin>: one "<size> <name>" line per entry, sorted (to compare TOCs)
                foreach (var line in new LegendaryExplorerCore.Unreal.TOCBinFile(args[1]).GetAllEntries()
                             .Select(e => $"{e.size} {e.name}").Order(StringComparer.OrdinalIgnoreCase))
                    Console.WriteLine(line);
                return 0;
            case "--write-yaml":
            {
                using var form = new MainForm(Profile(args[1]));
                File.WriteAllText(args[2], form.DefaultYaml(args.Length > 3 ? args[3] : "Shepard", args.Length > 4 ? args[4] : "Default"), new UTF8Encoding(false));
                return 0;
            }
        }
        throw new ArgumentException("unknown command " + args[0]);
    }
}

sealed class OptionDef
{
    public string Key, Display, Doc, Type;
    public JsonElement Default;
    public string[] Choices = [];
    public int Min, Max;
}

sealed class MainForm : Form
{
    const string AppName = "Mass Effect AP Setup";
    readonly string _here = AppContext.BaseDirectory;
    readonly TextBox _gameDir = new() { Width = 520 }, _apDir = new() { Width = 520 }, _modManager = new() { Width = 520 };
    readonly Label _status = new() { AutoSize = true, Font = new Font(FontFamily.GenericMonospace, 9) };
    readonly TextBox _help = new() { Multiline = true, ReadOnly = true, ScrollBars = ScrollBars.Vertical, Height = 150, Dock = DockStyle.Bottom };
    readonly TextBox _slot = new() { Width = 200, Text = "Shepard", MaxLength = 16 };
    readonly ComboBox _preset = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 200 };
    readonly ComboBox _game = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 220 };
    readonly CheckBox _launchClient = new() { AutoSize = true, Checked = true, Margin = new Padding(8, 6, 0, 0) };
    readonly FlowLayoutPanel _movies = new() { AutoSize = true, FlowDirection = FlowDirection.TopDown };
    readonly TabControl _tabs = new() { Dock = DockStyle.Fill };
    readonly Dictionary<string, Control> _controls = new();
    readonly List<OptionDef> _options = [];
    GameProfile _profile;
    JsonElement _schema;

    public MainForm(GameProfile only = null)
    {
        Text = $"{AppName} {Application.ProductVersion.Split('+')[0]} - Mass Effect Legendary Edition for Archipelago";
        Width = 920; Height = 780;
        var top = new FlowLayoutPanel { Dock = DockStyle.Top, AutoSize = true, Padding = new Padding(8) };
        top.Controls.Add(new Label { Text = "Game", AutoSize = true, Margin = new Padding(0, 6, 4, 0), Font = new Font(Font, FontStyle.Bold) });
        foreach (var p in GameProfile.All) _game.Items.Add(p.Title);
        top.Controls.Add(_game);
        Controls.Add(_tabs);
        Controls.Add(top);
        _game.SelectedIndexChanged += (_, _) => SelectGame(GameProfile.All[_game.SelectedIndex]);
        _game.SelectedIndex = only != null ? Array.IndexOf(GameProfile.All, only)
            : Math.Max(0, Array.FindIndex(GameProfile.All, p => Directory.Exists(Path.Combine(_here, p.Id))));
    }

    Installer Make() => new(_profile, _gameDir.Text, _apDir.Text, Path.Combine(_here, _profile.Id), Installer.DefaultStateDir(_profile));

    void SelectGame(GameProfile profile)
    {
        _profile = profile;
        using (var stream = typeof(MainForm).Assembly.GetManifestResourceStream(profile.OptionsResource))
            _schema = JsonDocument.Parse(stream).RootElement.Clone();
        _controls.Clear();
        _options.Clear();
        _tabs.TabPages.Clear();
        _tabs.TabPages.Add(PathsPage());
        _tabs.TabPages.Add(InstallPage());
        _tabs.TabPages.Add(OptionsPage());
        _tabs.SelectedIndexChanged -= TabChanged;
        _tabs.SelectedIndexChanged += TabChanged;
        DetectPaths();
        RefreshStatus();
    }

    void TabChanged(object sender, EventArgs e) => RefreshStatus();

    // ---------------------------------------------------------------- paths
    TabPage PathsPage()
    {
        var page = new TabPage("1. Folders");
        var flow = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.TopDown, Padding = new Padding(12), AutoScroll = true };
        flow.Controls.Add(new Label { AutoSize = true, MaximumSize = new Size(840, 0), Text =
            "Check the folders below (they are detected automatically; use Browse to change them), then go to Install.\n" +
            $"Mass Effect Legendary Edition: the folder that contains Game\\{_profile.GameFolder}. Archipelago: the folder with ArchipelagoLauncher.exe.\n" +
            (_profile.Loader == LoaderMode.RequireExisting
                ? "ME3Tweaks Mod Manager is needed once, for its ASI Manager (the ASI loader and LE1 Autoload Enabler); this app installs the mod itself."
                : "ME3Tweaks Mod Manager is optional: this app installs the mod and the ASI loader itself.") });
        flow.Controls.Add(PathRow("Mass Effect Legendary Edition folder", _gameDir, true));
        flow.Controls.Add(PathRow("Archipelago folder", _apDir, true));
        flow.Controls.Add(PathRow("ME3Tweaks Mod Manager (ME3TweaksModManager.exe)", _modManager, false));
        page.Controls.Add(flow);
        return page;
    }

    Control PathRow(string label, TextBox box, bool folder)
    {
        var panel = new FlowLayoutPanel { AutoSize = true, FlowDirection = FlowDirection.TopDown, Margin = new Padding(0, 10, 0, 0) };
        panel.Controls.Add(new Label { Text = label, AutoSize = true, Font = new Font(Font, FontStyle.Bold) });
        var row = new FlowLayoutPanel { AutoSize = true };
        var browse = new Button { Text = "Browse...", AutoSize = true };
        browse.Click += (_, _) =>
        {
            if (folder)
            {
                using var dialog = new FolderBrowserDialog { SelectedPath = box.Text };
                if (dialog.ShowDialog(this) == DialogResult.OK) box.Text = dialog.SelectedPath;
            }
            else
            {
                using var dialog = new OpenFileDialog { Filter = "ME3TweaksModManager.exe|ME3TweaksModManager.exe" };
                if (dialog.ShowDialog(this) == DialogResult.OK) box.Text = dialog.FileName;
            }
            RefreshStatus();
        };
        row.Controls.Add(box);
        row.Controls.Add(browse);
        panel.Controls.Add(row);
        return panel;
    }

    void DetectPaths()
    {
        if (_gameDir.Text.Length > 0 && _apDir.Text.Length > 0) return;   // kept when switching games
        var libraries = new List<string>();
        var steam = Registry.GetValue(@"HKEY_CURRENT_USER\Software\Valve\Steam", "SteamPath", null) as string;
        if (steam != null)
        {
            libraries.Add(steam);
            var vdf = Path.Combine(steam, "steamapps", "libraryfolders.vdf");
            if (File.Exists(vdf))
                foreach (var line in File.ReadAllLines(vdf))
                    if (line.Trim().StartsWith("\"path\""))
                        libraries.Add(line.Split('"')[3].Replace(@"\\", @"\"));
        }
        libraries.AddRange([@"C:\Program Files (x86)\Steam", @"C:\Steam", @"D:\Steam", @"D:\SteamLibrary", @"E:\SteamLibrary"]);
        var candidates = libraries.Select(l => Path.GetFullPath(Path.Combine(l, "steamapps", "common", "Mass Effect Legendary Edition")))
            .Append(@"C:\Program Files\EA Games\Mass Effect Legendary Edition");
        _gameDir.Text = candidates.FirstOrDefault(p => File.Exists(Path.Combine(p, "Game", _profile.GameFolder, "Binaries", "Win64", _profile.Exe))) ?? "";
        _apDir.Text = new[] { @"C:\ProgramData\Archipelago", Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Archipelago") }
            .FirstOrDefault(p => File.Exists(Path.Combine(p, "ArchipelagoLauncher.exe"))) ?? "";
        foreach (var root in new[] { Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                     Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Documents"),
                     Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Downloads") })
        {
            var found = FindFile(root, "ME3TweaksModManager.exe", 4);
            if (found != null) { _modManager.Text = found; break; }
        }
    }

    static string FindFile(string root, string name, int depth)
    {
        try
        {
            var direct = Path.Combine(root, name);
            if (File.Exists(direct)) return direct;
            if (depth == 0) return null;
            foreach (var dir in Directory.EnumerateDirectories(root))
                if (FindFile(dir, name, depth - 1) is { } hit) return hit;
        }
        catch (UnauthorizedAccessException) { }
        catch (IOException) { }
        return null;
    }

    // ---------------------------------------------------------------- install
    TabPage InstallPage()
    {
        var page = new TabPage("2. Install");
        var flow = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.TopDown, Padding = new Padding(12), AutoScroll = true };
        flow.Controls.Add(new Label { AutoSize = true, MaximumSize = new Size(840, 0), Text =
            $"Close {_profile.Title} and the Archipelago client first. Install (or Repair) copies the world into Archipelago, puts the bridge in " +
            $"the game's ASI folder and installs the mod" + (_profile.Toc == TocMode.Le1Basegame ? " with the game's file table (no AutoTOC needed)" : "") +
            (_profile.Loader == LoaderMode.ApLoader ? ", adding the AP ASI Loader unless a loader such as Mod Manager's is already there" : "") +
            ". Anything replaced is backed up, and Uninstall puts every file back as it was." });
        flow.Controls.Add(_status);
        _movies.Controls.Clear();
        foreach (var (file, label) in _profile.OptionalMovies)
            _movies.Controls.Add(new CheckBox { Text = $"{label} ({file})", Tag = file, AutoSize = true, Checked = true });
        if (_profile.OptionalMovies.Length > 0) flow.Controls.Add(_movies);
        var buttons = new FlowLayoutPanel { AutoSize = true };
        var install = new Button { Text = "Install / Repair", AutoSize = true };
        var uninstall = new Button { Text = "Uninstall", AutoSize = true };
        var launch = new Button { Text = $"Launch {_profile.Title}", AutoSize = true };
        _launchClient.Text = $"also start the {_profile.Client}";
        install.Click += (_, _) => Run(InstallAll);
        uninstall.Click += (_, _) => Run(() => { var i = Make(); i.Uninstall(); Report(i); });
        launch.Click += (_, _) => Run(LaunchGame);
        buttons.Controls.Add(install);
        buttons.Controls.Add(uninstall);
        buttons.Controls.Add(launch);
        buttons.Controls.Add(_launchClient);
        flow.Controls.Add(buttons);
        page.Controls.Add(flow);
        return page;
    }

    void Run(Action action)
    {
        try
        {
            if (Process.GetProcessesByName(_profile.ProcessName).Length > 0) throw new InvalidOperationException($"Close {_profile.Title} first.");
            action();
        }
        catch (Exception ex) { MessageBox.Show(this, ex.Message, AppName, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
        RefreshStatus();
    }

    void Report(Installer installer) => MessageBox.Show(this, string.Join("\r\n", installer.Log), AppName);

    void InstallAll()
    {
        var installer = Make();
        var options = new Installer.Options();
        foreach (CheckBox box in _movies.Controls)
            if (!box.Checked) options.KeepMovies.Add((string)box.Tag);
        installer.Install(options);
        Report(installer);
    }

    void RefreshStatus()
    {
        if (_profile == null) return;
        var i = Make();
        var lines = new StringBuilder();
        lines.AppendLine($"{_profile.Title + " LE",-22}: {(i.GameFound ? "found" : "NOT FOUND - set the folder on page 1")}");
        lines.AppendLine($"{"Archipelago",-22}: {(i.ArchipelagoFound ? "found" : "NOT FOUND - set the folder on page 1")}");
        lines.AppendLine($"{"ASI loader",-22}: {(i.GameFound ? i.LoaderState() : "-")}");
        foreach (var (pattern, name) in _profile.RequiredAsis)
            lines.AppendLine($"{name,-22}: {(!i.GameFound ? "-" : i.MissingRequirements().Contains(name) ? "MISSING (Mod Manager > ASI Manager)" : "installed")}");
        lines.AppendLine($"{"Archipelago world",-22}: {(i.ArchipelagoFound ? i.State(Path.Combine(i.Payload, _profile.Apworld), i.WorldTarget) : "-")}");
        foreach (var asi in _profile.AsiFiles)
            lines.AppendLine($"{asi,-22}: {(i.GameFound ? i.State(Path.Combine(i.Payload, "ASI", asi), Path.Combine(i.AsiDir, asi)) : "-")}");
        var mod = i.GameFound ? i.ModVersionInstalled() : null;
        lines.AppendLine($"{"Mod",-22}: {(!i.GameFound ? "-" : mod == null ? "not installed" : "installed, version " + mod + (i.ModVersionPayload() is { } v && v != mod ? $" (this release: {v})" : ""))}");
        lines.AppendLine($"{"Uninstall record",-22}: {(i.Installed ? "yes (Uninstall restores the earlier files)" : "none")}");
        _status.Text = lines.ToString();
    }

    void LaunchGame()
    {
        var installer = Make();
        var problems = installer.LaunchProblems();
        if (problems.Count > 0) throw new InvalidOperationException("Not ready to launch:\r\n\r\n" + string.Join("\r\n", problems));
        // Started directly; the Legendary Edition launcher may still open: pick the game there. Steam must be running.
        Process.Start(new ProcessStartInfo(installer.GameExe) { WorkingDirectory = installer.Win64, UseShellExecute = true });
        if (_launchClient.Checked)
            Process.Start(new ProcessStartInfo(Path.Combine(_apDir.Text, "ArchipelagoLauncher.exe"), $"\"{_profile.Client}\"")
                { WorkingDirectory = _apDir.Text, UseShellExecute = false });
    }

    void Generate()
    {
        var generator = Path.Combine(_apDir.Text, "ArchipelagoGenerate.exe");
        if (!File.Exists(generator)) throw new InvalidOperationException("ArchipelagoGenerate.exe not found: set the Archipelago folder on page 1.");
        if (!SaveYaml(null)) return;
        var players = Path.Combine(_apDir.Text, "Players");
        var yamls = Directory.GetFiles(players, "*.yaml").Select(Path.GetFileName).ToArray();
        if (MessageBox.Show(this, $"Generate a seed from every YAML in {players}?\r\n\r\n{string.Join("\r\n", yamls)}\r\n\r\n" +
                "Then upload the AP_*.zip from the output folder at archipelago.gg/uploads to host it.", AppName, MessageBoxButtons.YesNo) != DialogResult.Yes) return;
        using var run = Process.Start(new ProcessStartInfo(generator) { WorkingDirectory = _apDir.Text, UseShellExecute = true });
        run.WaitForExit();
        Process.Start(new ProcessStartInfo("explorer.exe", Path.Combine(_apDir.Text, "output")) { UseShellExecute = true });
    }

    // ---------------------------------------------------------------- options
    TabPage OptionsPage()
    {
        var page = new TabPage("3. Options");
        var top = new FlowLayoutPanel { Dock = DockStyle.Top, AutoSize = true, Padding = new Padding(8) };
        top.Controls.Add(new Label { Text = "Slot name", AutoSize = true, Margin = new Padding(0, 6, 4, 0) });
        top.Controls.Add(_slot);
        top.Controls.Add(new Label { Text = "Preset", AutoSize = true, Margin = new Padding(16, 6, 4, 0) });
        _preset.SelectedIndexChanged -= PresetChanged;
        _preset.Items.Clear();
        _preset.Items.Add("Default");
        foreach (var preset in _schema.GetProperty("presets").EnumerateObject()) _preset.Items.Add(preset.Name);
        _preset.SelectedIndex = 0;
        _preset.SelectedIndexChanged += PresetChanged;
        top.Controls.Add(_preset);
        var save = new Button { Text = "Save to Archipelago Players", AutoSize = true, Margin = new Padding(16, 2, 0, 0) };
        var saveAs = new Button { Text = "Save As...", AutoSize = true, Margin = new Padding(4, 2, 0, 0) };
        var generate = new Button { Text = "Save + Generate seed", AutoSize = true, Margin = new Padding(4, 2, 0, 0) };
        save.Click += (_, _) => SaveYaml(null);
        generate.Click += (_, _) =>
        {
            try { Generate(); }
            catch (Exception ex) { MessageBox.Show(this, ex.Message, AppName, MessageBoxButtons.OK, MessageBoxIcon.Warning); }
        };
        saveAs.Click += (_, _) =>
        {
            using var dialog = new SaveFileDialog { Filter = "YAML|*.yaml", FileName = SafeName() + ".yaml" };
            if (dialog.ShowDialog(this) == DialogResult.OK) SaveYaml(dialog.FileName);
        };
        top.Controls.Add(save);
        top.Controls.Add(saveAs);
        top.Controls.Add(generate);
        top.Controls.Add(new Label { AutoSize = true, MaximumSize = new Size(860, 0), Margin = new Padding(0, 8, 0, 0), Text = _profile.SaveNote });
        top.SetFlowBreak(generate, true);

        var groups = new TabControl { Dock = DockStyle.Fill };
        foreach (var group in _schema.GetProperty("groups").EnumerateArray())
        {
            var tab = new TabPage(group.GetProperty("name").GetString());
            var flow = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.TopDown, AutoScroll = true, WrapContents = false, Padding = new Padding(8) };
            foreach (var o in group.GetProperty("options").EnumerateArray())
            {
                var def = new OptionDef
                {
                    Key = o.GetProperty("key").GetString(), Display = o.GetProperty("display").GetString(),
                    Doc = o.GetProperty("doc").GetString(), Type = o.GetProperty("type").GetString(), Default = o.GetProperty("default").Clone(),
                };
                if (o.TryGetProperty("choices", out var choices)) def.Choices = choices.EnumerateArray().Select(c => c.GetString()).ToArray();
                if (def.Type == "range") { def.Min = o.GetProperty("min").GetInt32(); def.Max = o.GetProperty("max").GetInt32(); }
                _options.Add(def);
                flow.Controls.Add(OptionRow(def));
            }
            tab.Controls.Add(flow);
            groups.TabPages.Add(tab);
        }
        page.Controls.Add(groups);
        page.Controls.Add(_help);
        page.Controls.Add(top);
        _help.Text = "Pick a preset or set each option; click an option to read what it does. Save writes <slot>.yaml into Archipelago's Players folder.";
        ApplyPreset();
        return page;
    }

    void PresetChanged(object sender, EventArgs e) => ApplyPreset();

    Control OptionRow(OptionDef def)
    {
        var row = new FlowLayoutPanel { AutoSize = true, WrapContents = false, Margin = new Padding(0, 4, 0, 4) };
        var label = new Label { Text = def.Display, Width = 230, Margin = new Padding(0, 6, 8, 0) };
        Control input = def.Type switch
        {
            "toggle" => new CheckBox { Text = "on", AutoSize = true },
            "choice" => new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList, Width = 220 },
            "range" => new NumericUpDown { Minimum = def.Min, Maximum = def.Max, Width = 80 },
            _ => new CheckedListBox { Width = 260, Height = 20 * def.Choices.Length + 6, CheckOnClick = true },
        };
        if (input is CheckedListBox list) list.Items.AddRange(def.Choices);
        if (input is ComboBox combo) combo.Items.AddRange(def.Choices);
        void ShowHelp() => _help.Text = $"{def.Display}  ({def.Key})\r\n\r\n{def.Doc.Replace("\n", "\r\n")}";
        input.Enter += (_, _) => ShowHelp();
        input.Click += (_, _) => ShowHelp();
        label.Click += (_, _) => ShowHelp();
        _controls[def.Key] = input;
        row.Controls.Add(label);
        row.Controls.Add(input);
        return row;
    }

    void SetValue(OptionDef def, JsonElement value)
    {
        switch (_controls[def.Key])
        {
            case CheckBox box: box.Checked = value.ValueKind == JsonValueKind.True || (value.ValueKind == JsonValueKind.Number && value.GetInt32() != 0); break;
            case ComboBox combo: combo.SelectedItem = value.ValueKind == JsonValueKind.String ? value.GetString() : def.Choices[Math.Clamp(value.GetInt32(), 0, def.Choices.Length - 1)]; break;
            case NumericUpDown number: number.Value = Math.Clamp(value.GetInt32(), def.Min, def.Max); break;
            case CheckedListBox list:
                var on = value.EnumerateArray().Select(v => v.GetString()).ToHashSet();
                for (int i = 0; i < list.Items.Count; i++) list.SetItemChecked(i, on.Contains((string)list.Items[i]));
                break;
        }
    }

    void ApplyPreset()
    {
        foreach (var def in _options) SetValue(def, def.Default);
        if (_preset.SelectedIndex > 0 && _schema.GetProperty("presets").TryGetProperty((string)_preset.SelectedItem, out var preset))
            foreach (var entry in preset.EnumerateObject())
                if (_options.FirstOrDefault(d => d.Key == entry.Name) is { } def) SetValue(def, entry.Value);
    }

    string SafeName()
    {
        var name = string.Concat(_slot.Text.Trim().Where(c => !Path.GetInvalidFileNameChars().Contains(c)));
        return name.Length > 0 ? name : "Shepard";
    }

    static string Quote(string s) => "'" + s.Replace("'", "''") + "'";

    string BuildYaml()
    {
        var game = _schema.GetProperty("game").GetString();
        var yaml = new StringBuilder();
        yaml.AppendLine($"# Written by {AppName} {Application.ProductVersion.Split('+')[0]}. Put it in Archipelago's Players folder and run Generate.");
        yaml.AppendLine($"name: {Quote(_slot.Text.Trim().Length > 0 ? _slot.Text.Trim() : "Shepard")}");
        yaml.AppendLine($"description: {Quote(AppName + ", preset " + _preset.SelectedItem)}");
        yaml.AppendLine($"game: {Quote(game)}");
        yaml.AppendLine("requires:");
        yaml.AppendLine($"  version: {_schema.GetProperty("minimum_ap_version").GetString()}");
        yaml.AppendLine("  game:");
        yaml.AppendLine($"    {Quote(game)}: {_schema.GetProperty("world_version").GetString()}");
        yaml.AppendLine($"{Quote(game)}:");
        foreach (var def in _options)
        {
            var value = _controls[def.Key] switch
            {
                CheckBox box => box.Checked ? "'true'" : "'false'",
                ComboBox combo => Quote((string)combo.SelectedItem),
                NumericUpDown number => ((int)number.Value).ToString(),
                CheckedListBox list => "[" + string.Join(", ", list.CheckedItems.Cast<string>().Select(Quote)) + "]",
                _ => throw new InvalidOperationException(def.Key),
            };
            yaml.AppendLine($"  {def.Key}: {value}");
        }
        return yaml.ToString();
    }

    bool SaveYaml(string path)
    {
        if (path == null)
        {
            if (!File.Exists(Path.Combine(_apDir.Text, "ArchipelagoLauncher.exe")))
            {
                MessageBox.Show(this, "Set the Archipelago folder on page 1, or use Save As.", AppName);
                return false;
            }
            var players = Path.Combine(_apDir.Text, "Players");
            Directory.CreateDirectory(players);
            path = Path.Combine(players, SafeName() + ".yaml");
            if (File.Exists(path) && MessageBox.Show(this, $"{path} exists. Replace it?", AppName, MessageBoxButtons.YesNo) != DialogResult.Yes) return false;
        }
        File.WriteAllText(path, BuildYaml(), new UTF8Encoding(false));
        MessageBox.Show(this, $"Saved {path}", AppName);
        return true;
    }

    // used by the --write-yaml check: build the default YAML without showing the window
    public string DefaultYaml(string slot, string preset)
    {
        _slot.Text = slot;
        _preset.SelectedItem = preset;
        ApplyPreset();
        return BuildYaml();
    }
}
